metrics.workdir_dsl:
workspace "Parcel Tracker" "A C4 model of the parcel delivery tracking platform" {
    properties {
        "structurizr.feature.dsl.documentation" = "true"
    }

    model {
        customer = person "Customer" "Looks up the status of their parcels"

        parcelTracker = softwareSystem "Parcel Tracker" "Owned and operated by our company" {
            !docs "The Parcel Tracker is a system for tracking parcel deliveries."
            !decisions "The system is split into a web portal and a dispatch service."
            webPortal = container "Web Portal" "Where customers look up shipments" "Web Application"
            dispatchService = container "Dispatch Service" "Assigns parcels to couriers" "Service"
            pricingLibrary = container "Pricing Rules Library" "Computes delivery prices from weight and zone" "Library"
            database = container "Parcel Tracker Database" "Stores shipments and dispatch records" "Database"
        }

        emailProvider = softwareSystem "Email Delivery Provider" "Operated by a different organization"

        customer -> webPortal "Looks up the status of their parcels" "HTTPS"
        webPortal -> pricingLibrary "Uses" "In-process"
        dispatchService -> pricingLibrary "Uses" "In-process"
        dispatchService -> emailProvider "Sends customer notification emails" "SMTP"
        webPortal -> database "Stores and retrieves shipments" "SQL"
        dispatchService -> database "Stores dispatch records" "SQL"
    }

    views {
        systemContext parcelTracker "SystemContext" "A system context diagram of the Parcel Tracker" {
            include *
            autoLayout
        }
        container parcelTracker "Containers" "A container diagram of the Parcel Tracker" {
            include *
            autoLayout
        }
    }
}
